    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation/complex
        // properties that could cause non-deterministic seeds. DateTime.UtcNow is
        // evaluated at migration time, which is fine, but be aware of determinism.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = DateTime.UtcNow });
    }
}
