using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // EF Core 9 breaking change: Migrate() now runs inside its own transaction(s).
    // Calling it inside a user-opened transaction throws InvalidOperationException.
    // Fix: remove the wrapping transaction; use the execution strategy for retries only.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

