using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

// EF Core 9 Cosmos breaking change #1: The discriminator property is now
// named "$type" by default instead of "Discriminator".
// For existing documents that already use "Discriminator", you must explicitly
// configure the old property name to avoid query failures.

// EF Core 9 Cosmos breaking change #2: Synchronous I/O (e.g., ToList(),
// First(), SaveChanges()) now throws InvalidOperationException by default.
// Fix: use async equivalents (ToListAsync, FirstAsync, SaveChangesAsync).

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=FAKE==",
            "SampleDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasPartitionKey(p => p.Category);

            // Fix for existing documents: keep the old "Discriminator" property name
            entity.HasDiscriminator<string>("Discriminator")
                  .HasValue<Product>("Product")
                  .HasValue<DiscountedProduct>("DiscountedProduct");
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Category { get; set; } = null!;
}

class DiscountedProduct : Product
{
    public decimal Discount { get; set; }
}

using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

// EF Core 9 Cosmos breaking change: Synchronous I/O now throws by default.
// All queries/saves must use async methods.

class CosmosQueryService
{
    // BEFORE (EF Core 8 — worked but was blocking):
    //   var products = db.Products.ToList();
    //   var first = db.Products.First(p => p.Category == "Books");
    //   db.SaveChanges();

    // AFTER (EF Core 9 — async required):
    async Task<List<Product>> GetAllProductsAsync(CosmosDbContext db)
    {
        return await db.Products.ToListAsync();
    }

    async Task<Product> GetFirstInCategoryAsync(CosmosDbContext db, string category)
    {
        return await db.Products.FirstAsync(p => p.Category == category);
    }

    async Task SaveProductAsync(CosmosDbContext db, Product product)
    {
        db.Products.Add(product);
        await db.SaveChangesAsync();
    }
}

